 new DwResource( $this ,$resource );		 $dwResource->enableFullTrace();		 return $dwResource;		//*/	}	/*	protected function listen( string $srvUri = null ) : bool {		$return = false;		$iDwLogger = null;		if ( \method_exists( $this->log ,"upTo" ) )			$iDwLogger = $this->log->upTo( $this ,"listen" );		else			$iDwLogger = $this->log;				//$iDwLogger->trace("listen");		$dwResource = $this->createDwStreamSocket( $resource );		//$dwResource->listenTo( $this->dwPort );		$dwResources = $this->getDwServer()->getDwResources();		$this->dwResourceSelect = $dwResources->getResourceSelect( $this->log );		$this->dwStreamSelect->resourceRead(			$dwResource			,new \bakuba\kernel\objects\DwCallBack (				array( &$this ,"acceptConnection" )			)		);		$return = true;		$this->log->debug("-listen");				return $return;	}	//*/	private $peers = array();	public function acceptConnection( DwResource $dwResourceAccept ) : void {		$this->log->trace(".");		$dwResourceRead = $this->createDwResource( $dwResourceAccept->getResource() );		$this->newConnection( $dwResourceRead );				$$this->dwResourceSelect->resourceRead(			$dwResourceAccept			,new \bakuba\kernel\objects\DwCallBack( array( &$this ,"acceptConnection" ) )		);	}	protected function resourceConnexion( DwResource $dwResource ) : DwResourceConnexion {		return new DwResourceConnexion (			$this->dwResourceSelect			,$dwResource		);	}	public function newConnection( DwResource $dwResource ) : void {		$this->log->info( " Try Resource" );		$this->dwResourceSelect->getDwObjectTimer()->addTick(			$this->onConnect->getClone( $this->resourceConnexion( $dwResource ) )		);	}		///*	public function __destruct() {		//$this->log->trace( "." );		parent::__destruct();		foreach( $this as $key => $toDestruct )			if ( isset( $this->$key ) ) unset( $this->$key );	}	//*/	public function getClassName( bool $fqcn=null ) : string {		return self::getStaticClassName( $fqcn );	}	public static function getStaticClassName( bool $fqcn=null ) : string {		return $fqcn ? parent::getStaticClassName( $fqcn ).self::CLASS_SEPARATOR.__CLASS__ : __CLASS__;	}}?>